// Package reflect is the facade of the VM's Go-level reflect twin
// (github.com/traefik/yaegi/v2/vm, twin_*.go): the same API as package reflect
// (and its subset internal/reflectlite), over both VM values and native
// values.
//
// Packages generated by cmd/aotgen import it in place of reflect and
// internal/reflectlite:
//
//	import reflect "github.com/traefik/yaegi/v2/vreflect"
//
// so that their reflection sees the types and methods of the interpreted
// program.
package reflect

import (
	"reflect"
	"unsafe"

	"github.com/traefik/yaegi/v2/vm"
)

type (
	// Value mirrors reflect.Value.
	Value = vm.RV
	// Type mirrors reflect.Type (a canonical descriptor: == is type identity).
	Type = vm.RT
	// StructField mirrors reflect.StructField.
	StructField = vm.StructField
	// Method mirrors reflect.Method.
	Method = vm.RMethod
	// MapIter mirrors reflect.MapIter.
	MapIter = vm.MapIter
	// SelectCase mirrors reflect.SelectCase.
	SelectCase = vm.SelectCase

	Kind         = reflect.Kind
	ChanDir      = reflect.ChanDir
	SelectDir    = reflect.SelectDir
	StructTag    = reflect.StructTag
	ValueError   = reflect.ValueError
	SliceHeader  = reflect.SliceHeader  //nolint:staticcheck // mirrors reflect
	StringHeader = reflect.StringHeader //nolint:staticcheck // mirrors reflect
)

const (
	Invalid       = reflect.Invalid
	Bool          = reflect.Bool
	Int           = reflect.Int
	Int8          = reflect.Int8
	Int16         = reflect.Int16
	Int32         = reflect.Int32
	Int64         = reflect.Int64
	Uint          = reflect.Uint
	Uint8         = reflect.Uint8
	Uint16        = reflect.Uint16
	Uint32        = reflect.Uint32
	Uint64        = reflect.Uint64
	Uintptr       = reflect.Uintptr
	Float32       = reflect.Float32
	Float64       = reflect.Float64
	Complex64     = reflect.Complex64
	Complex128    = reflect.Complex128
	Array         = reflect.Array
	Chan          = reflect.Chan
	Func          = reflect.Func
	Interface     = reflect.Interface
	Map           = reflect.Map
	Pointer       = reflect.Pointer
	Ptr           = reflect.Ptr
	Slice         = reflect.Slice
	String        = reflect.String
	Struct        = reflect.Struct
	UnsafePointer = reflect.UnsafePointer

	RecvDir = reflect.RecvDir
	SendDir = reflect.SendDir
	BothDir = reflect.BothDir

	SelectSend    = reflect.SelectSend
	SelectRecv    = reflect.SelectRecv
	SelectDefault = reflect.SelectDefault
)

func Append(s Value, x ...Value) Value                       { return vm.Append(s, x...) }
func AppendSlice(s, t Value) Value                           { return vm.AppendSlice(s, t) }
func ArrayOf(length int, elem Type) Type                     { return vm.ArrayOf(length, elem) }
func ChanOf(dir ChanDir, t Type) Type                        { return vm.ChanOf(dir, t) }
func Copy(dst, src Value) int                                { return vm.Copy(dst, src) }
func DeepEqual(x, y any) bool                                { return vm.DeepEqual(x, y) }
func FuncOf(in, out []Type, variadic bool) Type              { return vm.FuncOf(in, out, variadic) }
func Indirect(v Value) Value                                 { return vm.Indirect(v) }
func MakeChan(typ Type, buffer int) Value                    { return vm.MakeChan(typ, buffer) }
func MakeFunc(typ Type, fn func(args []Value) []Value) Value { return vm.MakeFunc(typ, fn) }
func MakeMap(typ Type) Value                                 { return vm.MakeMap(typ) }
func MakeMapWithSize(typ Type, n int) Value                  { return vm.MakeMapWithSize(typ, n) }
func MakeSlice(typ Type, n, c int) Value                     { return vm.MakeSlice(typ, n, c) }
func MapOf(key, elem Type) Type                              { return vm.MapOf(key, elem) }
func New(typ Type) Value                                     { return vm.New(typ) }
func NewAt(typ Type, p unsafe.Pointer) Value                 { return vm.NewAt(typ, p) }
func PointerTo(t Type) Type                                  { return vm.PointerTo(t) }
func PtrTo(t Type) Type                                      { return vm.PtrTo(t) }
func Select(cases []SelectCase) (int, Value, bool)           { return vm.Select(cases) }
func SliceAt(typ Type, p unsafe.Pointer, n int) Value        { return vm.SliceAt(typ, p, n) }
func SliceOf(t Type) Type                                    { return vm.SliceOf(t) }
func StructOf(fields []StructField) Type                     { return vm.StructOf(fields) }
func Swapper(slice any) func(i, j int)                       { return vm.Swapper(slice) }
func TypeAssert[T any](v Value) (T, bool)                    { return vm.TypeAssert[T](v) }
func TypeFor[T any]() Type                                   { return vm.TypeFor[T]() }
func TypeOf(i any) Type                                      { return vm.TypeOf(i) }
func ValueOf(i any) Value                                    { return vm.ValueOf(i) }
func VisibleFields(t Type) []StructField                     { return vm.VisibleFields(t) }
func Zero(typ Type) Value                                    { return vm.Zero(typ) }
